package com.example.starter.consent.dto;

import com.example.starter.consent.Purpose;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

/**
 * 授权请求：按“主体＋用途”创建或复用当前有效授权代次，并为该 epoch 绑定唯一驻留区域。
 *
 * @param requestId  幂等请求标识，同一 requestId 相同参数重试返回原结果
 * @param subjectKey 主体标识（合成字符串）
 * @param purpose    用途：RESEARCH 研究 / PERSONALIZATION 个性化
 * @param region     驻留区域代码，必须预先登记；同 epoch 的区域不可直接修改，跨区域只能走迁移
 */
public record GrantRequest(
        @NotBlank @Size(max = 128) String requestId,
        @NotBlank @Size(max = 128) String subjectKey,
        @NotNull Purpose purpose,
        @NotBlank @Size(max = 32) @Pattern(regexp = "[A-Z][A-Z0-9_]*",
                message = "区域代码必须为大写字母开头的大写字母/数字/下划线组合") String region) {
}

package com.example.starter.consent.dto;

import com.example.starter.consent.GrantStatus;
import com.example.starter.consent.Purpose;

/**
 * 授权响应：返回主体、用途、代次、驻留区域与当前状态。
 *
 * @param subjectKey 主体标识（合成字符串）
 * @param purpose    用途：RESEARCH 研究 / PERSONALIZATION 个性化
 * @param epoch      授权代次，从 1 开始递增
 * @param region     本 epoch 数据驻留区域代码
 * @param status     状态：ACTIVE 有效 / REVOKED 已撤回
 */
public record GrantResponse(String subjectKey, Purpose purpose, int epoch, String region, GrantStatus status) {
}

package com.example.starter.consent.dto;

import com.example.starter.consent.Purpose;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

/**
 * 记录写入请求：仅当前有效代次可写入，且必须携带与 epoch 相同的驻留区域路由。
 *
