package com.example.starter.consent.dto;

import java.util.List;

import com.example.starter.consent.Purpose;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

/**
 * 跨对象查询请求：一次查询指定允许驻留区域集合与对象键集合。
 * 仅当授权有效、epoch 一致且所有对象驻留区域均在集合内时返回数据；任一不满足整次 403 或 410，不返回部分结果。
 *
 * @param requestId  查询幂等请求标识，同参重放返回首次完整快照，异参 409
 * @param subjectKey 主体标识（合成字符串）
 * @param purpose    用途：RESEARCH / PERSONALIZATION
 * @param regions    允许的驻留区域代码集合（至少一个）
 * @param recordKeys 待查询对象记录键集合（至少一个，去重后按字典序固化）
 */
public record QueryRequest(
        @NotBlank @Size(max = 128) String requestId,
        @NotBlank @Size(max = 128) String subjectKey,
        @NotNull Purpose purpose,
        @NotEmpty(message = "允许区域集合不能为空") List<@NotBlank @Pattern(regexp = "[A-Z][A-Z0-9_]*") String> regions,
        @NotEmpty(message = "查询对象集合不能为空") List<@NotBlank @Size(max = 128) String> recordKeys) {
}

package com.example.starter.consent.dto;

import java.time.Instant;
import java.util.List;

import com.example.starter.consent.Purpose;

/**
 * 跨对象查询响应：成功响应即合规快照，固化每个对象在查询时刻的 epoch、驻留区域与授权版本。
 *
 * @param snapshotId  快照标识（与 requestId 相同）
 * @param subjectKey  主体标识
 * @param purpose     用途
 * @param regions     本次允许的驻留区域集合（按字典序排序去重）
 * @param objects     对象快照列表（按 record_key 字典序排序，稳定排序与 null 语义）
 * @param objectCount 实际返回对象数量（实际值）
 * @param queriedAt   查询/快照生成时间（UTC）
 */
public record QueryResponse(String snapshotId, String subjectKey, Purpose purpose,
                            List<String> regions, List<SnapshotObject> objects,
                            int objectCount, Instant queriedAt) {

    /**
     * 单个对象的固化视图；后续迁移、撤回、清除均不改写已生成快照中的该对象。
     *
     * @param recordKey      记录键
     * @param epoch          查询时刻对象所属授权代次
     * @param region         查询时刻对象驻留区域代码
     * @param consentVersion 查询时刻对象授权版本
     * @param payload        查询时刻对象内容（合成字符串）
     */
    public record SnapshotObject(String recordKey, int epoch, String region,
                                 int consentVersion, String payload) {
    }
}

package com.example.starter.consent.dto;

import java.time.Instant;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.Size;

/**
 * 合法保留登记请求：撤回 epoch 下的记录在保留窗口（左闭右开，UTC）内仍允许受限读取。
 *
 * @param subjectKey 主体标识（合成字符串）
 * @param purpose    用途：RESEARCH / PERSONALIZATION
 * @param epoch      被保留记录所属授权代次
 * @param recordKey  被保留记录键
 * @param holdReason 保留依据（合成字符串，如合规案号）
 * @param validFrom  保留窗口起点（UTC，含）
 * @param validTo    保留窗口终点（UTC，不含），不得早于 validFrom
 */
public record LegalHoldRequest(
        @NotBlank @Size(max = 128) String subjectKey,
        @NotNull com.example.starter.consent.Purpose purpose,
        @NotNull @Positive Integer epoch,
        @NotBlank @Size(max = 128) String recordKey,
        @NotBlank @Size(max = 256) String holdReason,
        @NotNull Instant validFrom,
        @NotNull Instant validTo) {
}

