            storeSuccess(request.requestId(), OP_GRANT, fingerprint, response);
            return response;
        }
        response = new GrantResponse(request.subjectKey(), request.purpose(),
                nextEpoch, requestedRegion, GrantStatus.ACTIVE);
    }
    storeSuccess(request.requestId(), OP_GRANT, fingerprint, response);
    return response;
